snippet_css:
:root{
  --bg: #0A0A0F;
  --fg: #E0E0E0;
  --muted: #A8A8BE;
  --surface: #12121A;
  --border: #2A2A3A;
  --accent: #00F0FF;
  --accent-fg: #04161A;
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 0 0 1px rgba(0,240,255,.18),0 12px 30px rgba(0,0,0,.55);
  --btn-shadow: 0 0 0 1px rgba(0,240,255,.55),0 0 18px rgba(0,240,255,.35);
  --art-bg: linear-gradient(135deg,rgba(0,240,255,.22),rgba(255,0,60,.22)),repeating-linear-gradient(0deg,transparent 0 3px,rgba(0,240,255,.10) 3px 4px);
  --media-bg: linear-gradient(180deg,#12121A,#0A0A0F);
  --cta-bg: linear-gradient(180deg,#12121A,#0A0A0F);
  --input-bg: #0E0E16;
  --ok: #46E08A;
  --warn: #FF003C;
  --font-display: Orbitron,'Noto Sans TC',sans-serif;
  --font-body: Rajdhani,'Noto Sans TC',sans-serif;
  --font-mono: 'Share Tech Mono',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

